WITH l AS (SELECT * FROM bestiary_looks WHERE zone_id = {zone:Int64} AND mob_name = {name:String} AND capture_id NOT IN (SELECT capture_id FROM capture_trust FINAL WHERE trust = 'flagged')) SELECT 'speed' AS kind, [toString(speed), toString(speed_base), toString(toUInt8(coalesce(animation, 0) = 1))] AS key, sum(updates) AS updates, uniqExact(entity_id) AS mobs, uniqExact(capture_id) AS captures FROM l WHERE speed IS NOT NULL AND coalesce(animation, 0) NOT IN (2, 3) GROUP BY speed, speed_base, coalesce(animation, 0) = 1 UNION ALL SELECT 'model', [toString(coalesce(model_id, -1)), arrayStringConcat(arrayMap(x -> toString(x), look), ',')], sum(updates), uniqExact(entity_id), uniqExact(capture_id) FROM l GROUP BY model_id, look UNION ALL SELECT 'animation', [toString(animation)], sum(updates), uniqExact(entity_id), uniqExact(capture_id) FROM l WHERE animation IS NOT NULL GROUP BY animation UNION ALL SELECT 'flag', [flag], sum(updates), uniqExact(entity_id), uniqExact(capture_id) FROM l ARRAY JOIN flags AS flag GROUP BY flag UNION ALL SELECT 'flags', flags, sum(updates), uniqExact(entity_id), uniqExact(capture_id) FROM l GROUP BY flags UNION ALL SELECT 'widescan', [toString(toUInt8(listed))], 0, 0, count() FROM (SELECT capture_id, max(listed) AS listed FROM l WHERE scanned GROUP BY capture_id) GROUP BY listed
